    el.dataset.id = n.id; el.style.left = n.x + 'px'; el.style.top = n.y + 'px'; el.style.setProperty('--node-color', n.color || '#1687ff');
    el.innerHTML = `<span class="node-kind">${n.type === 'decision' ? 'DECISIÓN' : ''}</span><span class="node-label"></span>${['top', 'right', 'bottom', 'left'].map(p => `<button class="port ${p}" data-side="${p}" aria-label="Conectar hacia ${p}"></button>`).join('')}<span class="ghost-node"></span>`;
