function nodeSize(n) { return n.type === 'decision' ? { w: 120, h: 120 } : { w: 180, h: 72 }; }
function anchor(n, side) { const { w, h } = nodeSize(n); return { top: { x: n.x + w / 2, y: n.y }, right: { x: n.x + w, y: n.y + h / 2 }, bottom: { x: n.x + w / 2, y: n.y + h }, left: { x: n.x, y: n.y + h / 2 } }[side || 'right']; }
function opposite(side) { return { top: 'bottom', right: 'left', bottom: 'top', left: 'right' }[side]; }
function showGhost(e) { if (connectionDrag) return; const node = state.nodes.find(n => n.id === e.currentTarget.closest('.diagram-node').dataset.id), side = e.currentTarget.dataset.side, ghost = e.currentTarget.closest('.diagram-node').querySelector('.ghost-node'), offsets = { top: [0, -145], right: [225, 0], bottom: [0, 145], left: [-225, 0] }; ghost.style.transform = `translate(${offsets[side][0]}px,${offsets[side][1]}px)`; ghost.classList.add('show'); }
