function startConnection(e) { e.preventDefault(); e.stopPropagation(); const port = e.currentTarget, nodeId = port.closest('.diagram-node').dataset.id, side = port.dataset.side, node = state.nodes.find(n => n.id === nodeId), start = anchor(node, side); connectionDrag = { nodeId, side, start, startX: e.clientX, startY: e.clientY, moved: false }; port.setPointerCapture(e.pointerId); port.onpointermove = moveConnection; port.onpointerup = endConnection; $('connectionPreview').classList.remove('hidden'); hideGhost(e); }
function moveConnection(e) { if (!connectionDrag) return; connectionDrag.moved = Math.hypot(e.clientX - connectionDrag.startX, e.clientY - connectionDrag.startY) > 6; const rect = canvas.getBoundingClientRect(), end = { x: (e.clientX - rect.left) / state.zoom, y: (e.clientY - rect.top) / state.zoom }; $('connectionPreview').setAttribute('d', curvePath(connectionDrag.start, end)); }
function endConnection(e) { if (!connectionDrag) return; const info = connectionDrag; connectionDrag = null; $('connectionPreview').classList.add('hidden'); const targetEl = document.elementFromPoint(e.clientX, e.clientY)?.closest('.diagram-node'); if (info.moved && targetEl && targetEl.dataset.id !== info.nodeId) createEdge(info.nodeId, targetEl.dataset.id, info.side); else if (!info.moved) createDirectionalNode(info.nodeId, info.side); }
function createDirectionalNode(fromId, side) { const from = state.nodes.find(n => n.id === fromId), offset = { top: [0, -190], right: [280, 0], bottom: [0, 190], left: [-280, 0] }[side]; snapshot(); const id = safeId('Nuevo proceso'), node = { id, label: 'Nuevo proceso', x: from.x + offset[0], y: from.y + offset[1], type: 'node', color: from.color || null }; state.nodes.push(node); state.edges.push({ from: fromId, to: id, fromSide: side, toSide: opposite(side), label: '', shape: 'curve', direction: 'forward' }); state.selected = id; renderAll(); markChanged(); setTimeout(() => beginInlineEdit(id), 50); }
function createEdge(from, to, side = 'right') { snapshot(); state.edges.push({ from, to, fromSide: side, toSide: opposite(side), label: '', shape: 'curve', direction: 'forward' }); state.selected = null; state.selectedEdge = state.edges.length - 1; renderAll(); markChanged(); }
