    m = line.match(/^\s*%%\s*flowcharts?-edge:(\d+)\s+shape=(\w+)(?:\s+dashed=(true|false))?\s+fromSide=(\w+)\s+toSide=(\w+)(?:\s+labelPos=(\d+))?/); if (m) { metadata[+m[1]] = { shape: m[2], dashed: m[3] === 'true', fromSide: m[4], toSide: m[5], labelPos: Number(m[6] || 50) }; return; }
