async function chooseFolder() { if (!window.showDirectoryPicker) return showToast('Tu navegador no permite elegir carpetas'); try { directoryHandle = await window.showDirectoryPicker({ mode: 'readwrite' }); for await (const [name, handle] of directoryHandle.entries()) if (handle.kind === 'file' && /\.(text|txt)$/i.test(name)) await addRecent(handle, name); } catch (e) { if (e.name !== 'AbortError') showToast('No fue posible abrir la carpeta'); } }
