$('newDiagramBtn').onclick = () => { currentFileHandle = null; openEditor(sampleState()); }; $('openFolderBtn').onclick = chooseFolder; $('openFileBtn').onclick = openFile; $('fileInput').onchange = async e => { const f = e.target.files[0]; if (f) openFromText(await f.text(), f.name.replace(/\.(text|txt)$/i, '')); }; $('clearRecentBtn').onclick = async () => { const store = await recentStore('readwrite'); await new Promise(resolve => { const r = store.clear(); r.onsuccess = resolve; }); renderRecent(); };
