  state.edges.forEach((e,i)=>{out+=`  ${e.from} ${e.label?`-- "${e.label.replace(/"/g,"'")}" -->` : mermaidArrow(e)} ${e.to}\n  %% flowcharts-edge:${i} shape=${e.shape||'curve'} dashed=${!!e.dashed} fromSide=${e.fromSide||'right'} toSide=${e.toSide||'left'} labelPos=${e.labelPos??50}\n`});
