  groups.forEach(group=>{const members=nodes.filter(n=>n.group===group.id),memberIds=new Set(members.map(n=>n.id)),internal=edges.filter(e=>memberIds.has(e.from)&&memberIds.has(e.to));const bounds=layoutGraph(members,internal,cursorX,220);group.bounds=bounds;groupBounds.push(bounds);cursorX+=bounds.w+170});
